-- Generated by GMConverter. The client runtime for converted particle effects: it simulates each
-- effect's emitters from their exported definitions and draws them with the pixel shaders compiled
-- from their materials, on screenspace_general_8tex. Effects register with GMConverterFX.Register;
-- models register the effects their animations start with GMConverterFX.RegisterModel, and the
-- materials their source game lights its own way with GMConverterFX.RegisterShading. Every add-on
-- GMConverter writes ships this file; the newest version loaded wins.
--
-- Effect space: +X forward, +Y left, +Z up, in Source units, attached to an entity's attachment.

local VERSION = 5

if GMConverterFX and (GMConverterFX.version or 0) >= VERSION then return end

local FX = GMConverterFX or {}
GMConverterFX = FX
FX.version = VERSION
FX.effects = FX.effects or {}
FX.models = FX.models or {}
FX.active = FX.active or {}
FX.shaded = FX.shaded or {}

local random, floor, max, sqrt, sin, cos = math.random, math.floor, math.max, math.sqrt, math.sin, math.cos

--- Registers an effect: name -> { emitters = { ... } } as GMConverter writes it.
function FX.Register(name, definition)
	for index, emitter in ipairs(definition.emitters) do
		emitter.index = index
	end
	FX.effects[name] = definition
end

--- Registers the effects a model's sequences start: model path -> { [sequence] = { { time, effect, attachment }, ... } }.
function FX.RegisterModel(model, sequences)
	FX.models[string.lower(model)] = sequences
end

-- Curves are flat key lists: { t, v, t, v, ... } for numbers, { t, x, y, z, ... } for vectors, held past
-- their ends and linear between keys. A value is { min = keys, max = keys }; max is absent when equal.

local function sample1(keys, t)
	local n = #keys
	if n <= 2 or t <= keys[1] then return keys[2] end
	if t >= keys[n - 1] then return keys[n] end
	for i = 3, n - 1, 2 do
		if t <= keys[i] then
			local t0 = keys[i - 2]
			local f = (t - t0) / (keys[i] - t0)
			return keys[i - 1] + (keys[i + 1] - keys[i - 1]) * f
		end
	end
	return keys[n]
end

local function sample3(keys, t)
	local n = #keys
	if n <= 4 or t <= keys[1] then return keys[2], keys[3], keys[4] end
	if t >= keys[n - 3] then return keys[n - 2], keys[n - 1], keys[n] end
	for i = 5, n - 3, 4 do
		if t <= keys[i] then
			local t0 = keys[i - 4]
			local f = (t - t0) / (keys[i] - t0)
			return keys[i - 3] + (keys[i + 1] - keys[i - 3]) * f,
				keys[i - 2] + (keys[i + 2] - keys[i - 2]) * f,
				keys[i - 1] + (keys[i + 3] - keys[i - 1]) * f
		end
	end
	return keys[n - 2], keys[n - 1], keys[n]
end

local function floatAt(curve, t, r)
	local low = sample1(curve.min, t)
	if not curve.max then return low end
	return low + (sample1(curve.max, t) - low) * r
end

local function vectorAt(curve, t, rx, ry, rz)
	local x, y, z = sample3(curve.min, t)
	if not curve.max then return x, y, z end
	local hx, hy, hz = sample3(curve.max, t)
	return x + (hx - x) * rx, y + (hy - y) * ry, z + (hz - z) * rz
end

-- Materials: one per shader and vertex layout, created once.

local TEXTURE_PARAMS = { "$basetexture", "$texture1", "$texture2", "$texture3", "$texture4", "$texture5", "$texture6", "$texture7" }
local LINEAR_PARAMS = { "$linearread_basetexture", "$linearread_texture1", "$linearread_texture2", "$linearread_texture3",
	"$linearread_texture4", "$linearread_texture5", "$linearread_texture6", "$linearread_texture7" }

local materials = {}
local function material(def, layout)
	local key = def.shader .. "|" .. layout
	local cached = materials[key]
	if cached ~= nil then return cached or nil end
	local params = {
		["$pixshader"] = def.shader,
		["$vertexshader"] = layout == "mesh" and def.meshShader or def.spriteShader,
		["$cull"] = "0",
		["$depthtest"] = "1",
		["$vertexnormal"] = "1",
		["$vertexcolor"] = "1",
		["$tcsize0"] = "2", ["$tcsize1"] = "2", ["$tcsize2"] = "2", ["$tcsize3"] = "2",
	}
	for i, texture in ipairs(def.textures) do
		params[TEXTURE_PARAMS[i]] = texture[1]
		if texture[2] then params[LINEAR_PARAMS[i]] = "1" end
	end
	local mat = CreateMaterial("gmcfx_" .. def.shader .. "_" .. layout, "screenspace_general_8tex", params)
	if not mat or mat:IsError() then
		ErrorNoHalt("[GMConverter] Could not create effect material " .. def.shader .. "; screenspace_general_8tex needs Garry's Mod 2025.12 or newer.\n")
		materials[key] = false
		return nil
	end
	materials[key] = mat
	return mat
end

-- Mesh particles' models: triangle lists the exporter writes (count, then x y z u v per vertex).
local meshes = {}
local function particleMesh(path, mat)
	local cached = meshes[path]
	if cached ~= nil then return cached or nil end
	meshes[path] = false
	local f = file.Open(path, "rb", "GAME")
	if not f then
		ErrorNoHalt("[GMConverter] Missing effect mesh " .. path .. "\n")
		return nil
	end
	local count = f:ReadLong()
	local vertices = {}
	for i = 1, count do
		vertices[i] = { f:ReadFloat(), f:ReadFloat(), f:ReadFloat(), f:ReadFloat(), f:ReadFloat() }
	end
	f:Close()
	local imesh = Mesh(mat)
	mesh.Begin(imesh, MATERIAL_TRIANGLES, count / 3)
	local ok, err = pcall(function()
		for i = 1, count do
			local v = vertices[i]
			mesh.Position(Vector(v[1], v[2], v[3]))
			mesh.Normal(vector_up)
			mesh.TexCoord(0, v[4], v[5])
			mesh.AdvanceVertex()
		end
	end)
	mesh.End()
	if not ok then
		ErrorNoHalt("[GMConverter] Could not build effect mesh " .. path .. ": " .. tostring(err) .. "\n")
		return nil
	end
	meshes[path] = imesh
	return imesh
end

-- Source uploads render.SetModelLighting's ambient cube only when a model draws, so a hidden,
-- zero-scale model is drawn after setting it.
local commitModel
local function commitConstants()
	if not IsValid(commitModel) then
		commitModel = ClientsideModel("models/hunter/blocks/cube025x025x025.mdl", RENDERGROUP_OTHER)
		if not IsValid(commitModel) then return false end
		commitModel:SetNoDraw(true)
		commitModel:SetModelScale(0)
	end
	commitModel:DrawModel()
	return true
end

-- Lit models: materials drawn with their source game's shading, in place of the model's own
-- VertexLitGeneric materials (which stay as they are for clients without this runtime).

--- Registers a model's lit materials: model path -> { [material name] = { shader, vertexShader, textures = { { path, linear }, ... } } }.
function FX.RegisterShading(model, definitions)
	FX.shaded[string.lower(model)] = definitions
end

local BRDF_TEXTURE = "gmconverter/shading/environment_brdf"
local PROBE_SAMPLER, BRDF_SAMPLER = 7, 8 -- 1-based, as TEXTURE_PARAMS

-- The limit CrossFire HD maps put on the GGX distribution (WorldInfo.GGXMaxStrength); Source maps
-- have none, so none by default.
local fullbright = GetConVar("mat_fullbright")
local ggxLimit = CreateClientConVar("gmconverter_ggx_limit", "0", true, false, "Largest GGX distribution value lit GMConverter materials use; 0 for none.")

local litMaterials = {}
local function litMaterial(def)
	local cached = litMaterials[def.shader]
	if cached ~= nil then return cached or nil end
	local params = {
		["$pixshader"] = def.shader,
		["$vertexshader"] = def.vertexShader,
		["$cull"] = "0",
		["$depthtest"] = "1",
		["$model"] = "1",
		["$softwareskin"] = "1",
		["$vertexnormal"] = "1",
		[TEXTURE_PARAMS[BRDF_SAMPLER]] = BRDF_TEXTURE,
		[LINEAR_PARAMS[BRDF_SAMPLER]] = "1",
	}
	for i, texture in ipairs(def.textures) do
		params[TEXTURE_PARAMS[i]] = texture[1]
		if texture[2] then params[LINEAR_PARAMS[i]] = "1" end
	end
	local mat = CreateMaterial("gmcsh_" .. def.shader, "screenspace_general_8tex", params)
	if not mat or mat:IsError() then
		ErrorNoHalt("[GMConverter] Could not create lit material " .. def.shader .. "; screenspace_general_8tex needs Garry's Mod 2025.12 or newer.\n")
		litMaterials[def.shader] = false
		return nil
	end
	litMaterials[def.shader] = mat
	return mat
end

-- Source commits a model's lighting only for its own shaders. A hidden bump-mapped, phong-lit
-- VertexLitGeneric model drawn just before, centred where the lit model is, leaves its ambient cube
-- and lights in the shader constants (without phong the light registers aren't filled), and its
-- $envmap names the cubemap Source picks there.
local lightingModel, lightingMaterial
local function commitLighting(center)
	if not IsValid(lightingModel) then
		lightingModel = ClientsideModel("models/props_junk/PopCan01a.mdl", RENDERGROUP_OTHER)
		if not IsValid(lightingModel) then return nil end
		lightingModel:SetNoDraw(true)
		lightingMaterial = CreateMaterial("gmcsh_lighting", "VertexLitGeneric", {
			["$basetexture"] = "color/white",
			["$bumpmap"] = "dev/bump_normal",
			["$phong"] = "1",
			["$phongexponent"] = "20",
			["$phongboost"] = "1",
			["$phongfresnelranges"] = "[0 0.5 1]",
			["$envmap"] = "env_cubemap",
		})
		lightingModel:SetMaterial("!gmcsh_lighting")
	end
	lightingModel:SetPos(center - (lightingModel:WorldSpaceCenter() - lightingModel:GetPos()))
	render.OverrideColorWriteEnable(true, false)
	render.OverrideDepthEnable(true, false)
	lightingModel:DrawModel()
	render.OverrideDepthEnable(false)
	render.OverrideColorWriteEnable(false)
	return lightingMaterial:GetTexture("$envmap")
end

-- Overrides the entity's lit materials for its next draw; false when it has none.
local shadedIndices = setmetatable({}, { __mode = "k" })
local function beginShading(ent, center)
	local model = string.lower(ent:GetModel() or "")
	local defs = FX.shaded[model]
	if not defs then return false end
	local indices = shadedIndices[ent]
	if not indices or indices.model ~= model then
		indices = { model = model }
		for i, path in ipairs(ent:GetMaterials()) do
			local def = defs[string.lower(string.GetFileFromFilename(path))]
			if def then indices[#indices + 1] = { i - 1, def } end
		end
		shadedIndices[ent] = indices
	end
	if #indices == 0 then return false end
	local probe = commitLighting(center)
	if not probe then return false end
	local limit = ggxLimit:GetFloat()
	local lastMip = math.max(0, math.log(math.max(probe:Width(), 1), 2))
	for _, entry in ipairs(indices) do
		local mat = litMaterial(entry[2])
		if mat then
			mat:SetTexture(TEXTURE_PARAMS[PROBE_SAMPLER], probe)
			mat:SetFloat("$c0_x", CurTime())
			mat:SetFloat("$c0_y", limit > 0 and limit or 1e30)
			mat:SetFloat("$c0_z", 1)
			mat:SetFloat("$c0_w", lastMip)
			mat:SetFloat("$c1_x", fullbright:GetInt() ~= 0 and 1 or 0)
			render.MaterialOverrideByIndex(entry[1], mat)
		end
	end
	return true
end

local function endShading()
	render.MaterialOverrideByIndex()
end

-- Instances

local function frameOf(instance)
	local ent = instance.entity
	if IsValid(ent) then
		if instance.attachment and instance.attachment > 0 then
			local point = ent:GetAttachment(instance.attachment)
			if point then return point.Pos, point.Ang end
		end
		return ent:GetPos(), ent:GetAngles()
	end
	return instance.pos or vector_origin, instance.ang or angle_zero
end

-- Simulation follows Cascade's tick: particles past their life die, the rest age and update, new
-- ones are released (each already as far into its life as its share of the frame), orbits turn, and
-- everything moves. Values a particle picks from a random range over its life are picked again each
-- frame, as Cascade's distributions are.

-- Particles raise events where they are born and die; emitters listening for them release theirs there
-- once every emitter has ticked. An event keeps its position (in its emitter's space) and its emitter's
-- time, which the listener's count is looked up by.
local function raise(instance, emitter, kind, p, emitterTime)
	local listeners = emitter.listeners and emitter.listeners[kind]
	if not listeners then return end
	local queue = instance.events
	queue[#queue + 1] = { listeners = listeners, x = p.x, y = p.y, z = p.z, localSpace = emitter.localSpace, time = emitterTime }
end

-- Turns (x, y, z) by Rz(rz)*Ry(ry)*Rx(rx): right-handed, about X first.
local function rotateXYZ(rx, ry, rz, x, y, z)
	local c, s = cos(rx), sin(rx)
	y, z = y * c - z * s, y * s + z * c
	c, s = cos(ry), sin(ry)
	x, z = x * c + z * s, z * c - x * s
	c, s = cos(rz), sin(rz)
	x, y = x * c - y * s, x * s + y * c
	return x, y, z
end

-- An orbit value from its distribution, by the particle's age or the emitter's time.
local function orbitValue(curve, timing, p, emitterTime)
	return vectorAt(curve, timing.emitterTime and emitterTime or p.rel, random(), random(), random())
end

local function spawnParticle(instance, state, emitter, emitterTime, spawnTime, origin)
	if #state.particles >= emitter.max then return end
	local life = floatAt(emitter.life, emitterTime, random())
	if life <= 0 then return end
	-- Released part-way through the frame, it is already that far into its life; one that would
	-- already be past it is never seen.
	local p = { life = life, rel = spawnTime / life }
	if p.rel > 1 then return end

	local lx, ly, lz = 0, 0, 0
	if emitter.location then lx, ly, lz = vectorAt(emitter.location, emitterTime, random(), random(), random()) end
	local vx, vy, vz = 0, 0, 0
	if emitter.velocity then vx, vy, vz = vectorAt(emitter.velocity, emitterTime, random(), random(), random()) end
	if emitter.radial then
		local speed = floatAt(emitter.radial, emitterTime, random())
		local length = sqrt(lx * lx + ly * ly + lz * lz)
		if length > 1e-6 then
			vx, vy, vz = vx + lx / length * speed, vy + ly / length * speed, vz + lz / length * speed
		end
	end

	p.sx, p.sy, p.sz = vectorAt(emitter.size, emitterTime, random(), random(), random())
	p.r, p.g, p.b = vectorAt(emitter.color, emitterTime, random(), random(), random())
	p.a = floatAt(emitter.alpha, emitterTime, random())
	p.roll = emitter.rotation and floatAt(emitter.rotation, emitterTime, random()) or 0
	p.spin = emitter.rotationRate and floatAt(emitter.rotationRate, emitterTime, random()) or 0
	if emitter.sheet and not emitter.sheet.frames then
		p.frame = floor(random() * emitter.sheet.columns * emitter.sheet.rows)
	end
	local orbit = emitter.orbit
	if orbit then
		-- What the spawn picks is the base the per-frame picks add to.
		local o = { base = { 0, 0, 0 }, rot = { 0, 0, 0 }, baseRate = { 0, 0, 0 }, prev = { 0, 0, 0 } }
		if orbit.offsetTiming.spawn then o.base = { orbitValue(orbit.offset, orbit.offsetTiming, p, emitterTime) } end
		if orbit.rotationTiming.spawn then o.rot = { orbitValue(orbit.rotation, orbit.rotationTiming, p, emitterTime) } end
		if orbit.rateTiming.spawn then o.baseRate = { orbitValue(orbit.rate, orbit.rateTiming, p, emitterTime) } end
		o.offset = { o.base[1], o.base[2], o.base[3] }
		o.rate = { o.baseRate[1], o.baseRate[2], o.baseRate[3] }
		p.orbit = o
	end

	local pos, ang = frameOf(instance)
	if origin then
		-- Released at another particle's event: there, offset by the location in the effect's axes.
		local ox, oy, oz = origin.x, origin.y, origin.z
		if origin.localSpace and not emitter.localSpace then
			local world = LocalToWorld(Vector(ox, oy, oz), angle_zero, pos, ang)
			ox, oy, oz = world.x, world.y, world.z
		elseif emitter.localSpace and not origin.localSpace then
			local localPos = WorldToLocal(Vector(ox, oy, oz), angle_zero, pos, ang)
			ox, oy, oz = localPos.x, localPos.y, localPos.z
		end
		if not emitter.localSpace then
			local offset = Vector(lx, ly, lz)
			offset:Rotate(ang)
			lx, ly, lz = offset.x, offset.y, offset.z
		end
		lx, ly, lz = ox + lx, oy + ly, oz + lz
	elseif not emitter.localSpace then
		local world = LocalToWorld(Vector(lx, ly, lz), angle_zero, pos, ang)
		lx, ly, lz = world.x, world.y, world.z
	end
	if not emitter.localSpace then
		local velocity = Vector(vx, vy, vz)
		velocity:Rotate(ang)
		vx, vy, vz = velocity.x, velocity.y, velocity.z
		p.ang = Angle(ang.p, ang.y, ang.r)
	end
	-- It has moved for its share of the frame already.
	p.bvx, p.bvy, p.bvz = vx, vy, vz
	p.vx, p.vy, p.vz = vx, vy, vz
	p.x, p.y, p.z = lx + vx * spawnTime, ly + vy * spawnTime, lz + vz * spawnTime
	p.oldx, p.oldy, p.oldz = lx, ly, lz
	state.particles[#state.particles + 1] = p
	raise(instance, emitter, "spawn", p, emitterTime)
end

local function worldPosition(instance, emitter, x, y, z)
	if not emitter.localSpace then return Vector(x, y, z) end
	local pos, ang = frameOf(instance)
	return LocalToWorld(Vector(x, y, z), angle_zero, pos, ang)
end

local function spawnAt(instance, emitter, emitterTime, count, spawnTime, origin)
	local state = instance.states[emitter.index]
	for _ = 1, count do spawnParticle(instance, state, emitter, emitterTime, spawnTime, origin) end
end

-- The emitter's cycle and its time within it.
local function clock(emitter, time)
	local emitterTime = max(time - emitter.delay, 0)
	local duration = emitter.duration
	if duration <= 0 then return 0, emitterTime end
	local cycle = floor(emitterTime / duration)
	return cycle, emitterTime - cycle * duration
end

-- Releases this frame's particles by rate and burst; returns whether the emitter may release more.
local function schedule(instance, emitter, state, time, dt)
	if time < emitter.delay then return true end
	local duration = emitter.duration
	local cycle, cycleTime = clock(emitter, time)
	if emitter.loops > 0 and cycle >= emitter.loops then return false end
	if instance.stopping then return false end
	if cycle ~= state.cycle then
		state.cycle = cycle
		state.fired = {}
	end
	-- A burst's particles share one start, a burst-sized slice into the frame.
	for i, burst in ipairs(emitter.bursts) do
		if not state.fired[i] and cycleTime >= burst[1] then
			state.fired[i] = true
			local count = random(burst[2], burst[3])
			if count > 0 then spawnAt(instance, emitter, cycleTime, count, dt / count) end
		end
	end
	-- By rate, the frame's particles share the start the earliest of them was due.
	if emitter.rate then
		local rate = max(floatAt(emitter.rate, cycleTime, random()), 0)
		local owed = state.accumulated + dt * rate
		local count = floor(owed)
		if count > 0 then spawnAt(instance, emitter, cycleTime, count, dt + (state.accumulated - 1) / rate) end
		state.accumulated = owed - count
	end
	if duration > 0 or emitter.rate then return true end
	-- Without a cycle, an emitter that only bursts is done once every burst has fired.
	for i in ipairs(emitter.bursts) do
		if not state.fired[i] then return true end
	end
	return false
end

local function tickEmitter(instance, emitter, state, time, dt)
	local particles = state.particles
	local _, emitterTime = clock(emitter, time)
	local i = 1
	while i <= #particles do
		local p = particles[i]
		if p.rel > 1 then
			raise(instance, emitter, "death", p, emitterTime)
			particles[i] = particles[#particles]
			particles[#particles] = nil
		else
			i = i + 1
		end
	end

	local ax, ay, az = emitter.acceleration[1], emitter.acceleration[2], emitter.acceleration[3]
	if not emitter.localSpace then
		local accel = Vector(ax, ay, az)
		accel:Rotate(select(2, frameOf(instance)))
		ax, ay, az = accel.x, accel.y, accel.z
	end
	local drag, orbit = emitter.drag, emitter.orbit
	for _, p in ipairs(particles) do
		p.rel = p.rel + dt / p.life
		p.bvx, p.bvy, p.bvz = p.bvx + ax * dt, p.bvy + ay * dt, p.bvz + az * dt
		if drag > 0 then
			local keep = max(0, 1 - drag * dt)
			p.bvx, p.bvy, p.bvz = p.bvx * keep, p.bvy * keep, p.bvz * keep
		end
		local kx, ky, kz = 1, 1, 1
		if emitter.velocityOverLife then kx, ky, kz = vectorAt(emitter.velocityOverLife, p.rel, random(), random(), random()) end
		p.vx, p.vy, p.vz = p.bvx * kx, p.bvy * ky, p.bvz * kz
		if orbit then
			-- Each frame starts from the spawn's picks; what is picked every frame adds to them (to the
			-- rotation, cumulatively). The drawn offset of the last frame is where the particle was drawn.
			local o = p.orbit
			o.prev = o.offset
			o.offset = { o.base[1], o.base[2], o.base[3] }
			o.rate = { o.baseRate[1], o.baseRate[2], o.baseRate[3] }
			if orbit.offsetTiming.frame then
				o.prev = { o.offset[1], o.offset[2], o.offset[3] }
				local x, y, z = orbitValue(orbit.offset, orbit.offsetTiming, p, emitterTime)
				o.offset = { o.offset[1] + x, o.offset[2] + y, o.offset[3] + z }
			end
			if orbit.rotationTiming.frame then
				local x, y, z = orbitValue(orbit.rotation, orbit.rotationTiming, p, emitterTime)
				o.rot = { o.rot[1] + x, o.rot[2] + y, o.rot[3] + z }
			end
			if orbit.rateTiming.frame then
				local x, y, z = orbitValue(orbit.rate, orbit.rateTiming, p, emitterTime)
				o.rate = { o.rate[1] + x, o.rate[2] + y, o.rate[3] + z }
			end
		end
	end

	local releasing = schedule(instance, emitter, state, time, dt)

	for _, p in ipairs(particles) do
		local o = p.orbit
		if o then
			o.rot = { o.rot[1] + o.rate[1] * dt, o.rot[2] + o.rate[2] * dt, o.rot[3] + o.rate[3] * dt }
			o.offset = { rotateXYZ(o.rot[1], o.rot[2], o.rot[3], o.offset[1], o.offset[2], o.offset[3]) }
		end
		p.oldx, p.oldy, p.oldz = p.x, p.y, p.z
		p.x, p.y, p.z = p.x + p.vx * dt, p.y + p.vy * dt, p.z + p.vz * dt
		p.roll = p.roll + p.spin * dt
	end
	return releasing or #particles > 0
end

local function simulate(instance, dt)
	instance.time = instance.time + dt
	local time = instance.time
	local alive = false
	local emitters = instance.effect.emitters
	for index, emitter in ipairs(emitters) do
		if tickEmitter(instance, emitter, instance.states[index], time, dt) then alive = true end
	end
	-- Events reach their listeners after every emitter has ticked, a whole frame into their lives;
	-- ones raised meanwhile wait a frame.
	local events = instance.events
	instance.events = {}
	for _, event in ipairs(events) do
		for _, listener in ipairs(event.listeners) do
			local child = emitters[listener.emitter]
			local _, childTime = clock(child, time)
			spawnAt(instance, child, childTime, floor(floatAt(listener.count, event.time, random()) + 0.5), dt, event)
			alive = true
		end
	end
	return alive or #instance.events > 0
end

-- Drawing

local function particleValues(emitter, p)
	local age = p.rel
	local sx, sy, sz = p.sx, p.sy, p.sz
	if emitter.sizeOverLife then
		local kx, ky, kz = vectorAt(emitter.sizeOverLife, age, random(), random(), random())
		sx, sy, sz = sx * kx, sy * ky, sz * kz
	end
	local r, g, b = p.r, p.g, p.b
	if emitter.colorOverLife then r, g, b = vectorAt(emitter.colorOverLife, age, random(), random(), random()) end
	local a = emitter.alphaOverLife and floatAt(emitter.alphaOverLife, age, random()) or p.a
	local params = emitter.params
	local p1 = params[1] and floatAt(params[1], age, random()) or 0
	local p2 = params[2] and floatAt(params[2], age, random()) or 0
	local p3 = params[3] and floatAt(params[3], age, random()) or 0
	local p4 = params[4] and floatAt(params[4], age, random()) or 0
	return age, sx, sy, sz, r, g, b, a, p1, p2, p3, p4
end

local function setBlend(def)
	if def.blend == "additive" then
		render.OverrideBlend(true, BLEND_ONE, BLEND_ONE, BLENDFUNC_ADD)
	elseif def.blend == "translucent" then
		render.OverrideBlend(true, BLEND_SRC_ALPHA, BLEND_ONE_MINUS_SRC_ALPHA, BLENDFUNC_ADD)
	end
end

local function setTime(time)
	render.SetModelLighting(4, time % 1000, 0, 0)
end

local function drawMeshes(instance, emitter, state, time)
	local mat = material(emitter.material, "mesh")
	if not mat then return end
	local imesh = particleMesh(emitter.mesh, mat)
	if not imesh then return end
	local pos, ang = frameOf(instance)
	setBlend(emitter.material)
	for _, p in ipairs(state.particles) do
		local age, sx, sy, sz, r, g, b, a, p1, p2, p3, p4 = particleValues(emitter, p)
		render.SetModelLighting(0, r, g, b)
		render.SetModelLighting(1, a, age, 0)
		render.SetModelLighting(2, p1, p2, p3)
		render.SetModelLighting(3, p4, 0, 0)
		setTime(time)
		render.SetModelLighting(5, 0, 0, 0)
		if commitConstants() then
			local matrix = Matrix()
			if emitter.localSpace then
				matrix:SetTranslation(pos)
				matrix:SetAngles(ang)
				matrix:Translate(Vector(p.x, p.y, p.z))
			else
				matrix:SetTranslation(Vector(p.x, p.y, p.z))
				matrix:SetAngles(p.ang)
			end
			matrix:Scale(Vector(sx, sy, sz))
			render.SetMaterial(mat)
			cam.PushModelMatrix(matrix)
			imesh:Draw()
			cam.PopModelMatrix()
		end
	end
	render.OverrideBlend(false)
end

local function drawSprites(instance, emitter, state, time)
	local particles = state.particles
	if #particles == 0 then return end
	local mat = material(emitter.material, "sprite")
	if not mat then return end
	local _, ang = frameOf(instance)
	local eye = EyePos()
	local view = EyeAngles()
	local right, up = view:Right(), view:Up()
	local sheet = emitter.sheet
	setTime(time)
	if not commitConstants() then return end
	setBlend(emitter.material)
	render.SetMaterial(mat)
	-- Quads are built in world space; the constants' model left its (zero) scale as the model matrix.
	cam.PushModelMatrix(Matrix())
	mesh.Begin(MATERIAL_QUADS, #particles)
	local ok, err = pcall(function()
		for _, p in ipairs(particles) do
			local age, sx, sy, _, r, g, b, a, p1, p2, p3, p4 = particleValues(emitter, p)
			-- Square sprites are as tall as they are wide.
			if emitter.alignment == 2 then sy = sx end
			-- Drawn at its position plus its orbit's offset, both in the emitter's space.
			local x, y, z = p.x, p.y, p.z
			local ox, oy, oz = p.oldx, p.oldy, p.oldz
			local o = p.orbit
			if o then
				x, y, z = x + o.offset[1], y + o.offset[2], z + o.offset[3]
				ox, oy, oz = ox + o.prev[1], oy + o.prev[2], oz + o.prev[3]
			end
			local center = worldPosition(instance, emitter, x, y, z)
			local hidden = false
			if emitter.cameraOffset then
				-- Drawn nearer the camera, in front of the surface the effect sits in; one whose offset
				-- would reach the camera isn't drawn.
				local toEye = eye - center
				local distance = toEye:Length()
				local offset = floatAt(emitter.cameraOffset, age, random())
				if distance > offset and distance > 1e-6 then
					center = center + toEye * (offset / distance)
				else
					hidden = true
				end
			end
			local axisX, axisY
			if emitter.alignment == 1 then
				-- Stretched along how far it was drawn from last frame, orbit included.
				local moved = Vector(x - ox, y - oy, z - oz)
				if emitter.localSpace then moved:Rotate(ang) end
				if moved:LengthSqr() < 1e-12 then moved = up end
				axisY = moved:GetNormalized()
				axisX = axisY:Cross(center - eye):GetNormalized()
			else
				local c, s = cos(p.roll), sin(p.roll)
				axisX = right * c + up * s
				axisY = up * c - right * s
			end
			if hidden then sx, sy = 0, 0 end
			local hx, hy = axisX * (sx * 0.5), axisY * (sy * 0.5)
			local u0, v0, u1, v1 = 0, 0, 1, 1
			if sheet then
				local frame = p.frame or floor(floatAt(sheet.frames, age, random()))
				local count = sheet.columns * sheet.rows
				frame = ((frame % count) + count) % count
				local column, row = frame % sheet.columns, floor(frame / sheet.columns)
				u0, u1 = column / sheet.columns, (column + 1) / sheet.columns
				v0, v1 = row / sheet.rows, (row + 1) / sheet.rows
			end
			local color = Vector(r, g, b)
			local corners = {
				{ center - hx - hy, u0, v1 }, { center + hx - hy, u1, v1 },
				{ center + hx + hy, u1, v0 }, { center - hx + hy, u0, v0 },
			}
			for _, corner in ipairs(corners) do
				mesh.Position(corner[1])
				mesh.Normal(color)
				mesh.Color(255, 255, 255, 255)
				mesh.TexCoord(0, corner[2], corner[3])
				mesh.TexCoord(1, a, age)
				mesh.TexCoord(2, p1, p2)
				mesh.TexCoord(3, p3, p4)
				mesh.AdvanceVertex()
			end
		end
	end)
	mesh.End()
	cam.PopModelMatrix()
	render.OverrideBlend(false)
	if not ok then ErrorNoHalt("[GMConverter] Effect draw failed: " .. tostring(err) .. "\n") end
end

local function draw(instance)
	local time = CurTime()
	render.SuppressEngineLighting(true)
	render.OverrideDepthEnable(true, false)
	for index, emitter in ipairs(instance.effect.emitters) do
		local state = instance.states[index]
		if #state.particles > 0 then
			if emitter.mesh then drawMeshes(instance, emitter, state, time) else drawSprites(instance, emitter, state, time) end
		end
	end
	render.OverrideDepthEnable(false, false)
	render.SuppressEngineLighting(false)
	render.ResetModelLighting(1, 1, 1)
end

--- Starts an effect on an entity's attachment (by name), or at pos/ang without one; returns the instance.
function FX.Play(name, entity, attachmentName, viewModel, pos, ang)
	local effect = FX.effects[name]
	if not effect then return nil end
	if not effect.linked then
		effect.linked = true
		for index, emitter in ipairs(effect.emitters) do
			for _, eventSpawn in ipairs(emitter.events or {}) do
				for _, source in ipairs(eventSpawn.sources) do
					local from = effect.emitters[source[1]]
					if from then
						from.listeners = from.listeners or {}
						from.listeners[source[2]] = from.listeners[source[2]] or {}
						table.insert(from.listeners[source[2]], { emitter = index, count = eventSpawn.count })
					end
				end
			end
		end
	end
	local instance = {
		effect = effect, name = name, entity = entity, viewModel = viewModel and true or false,
		attachment = IsValid(entity) and attachmentName and entity:LookupAttachment(attachmentName) or nil,
		pos = pos, ang = ang, time = 0, states = {}, events = {}, last = CurTime(),
	}
	for index in ipairs(effect.emitters) do
		instance.states[index] = { particles = {}, accumulated = 0, rateRandom = random(), fired = {}, cycle = -1 }
	end
	FX.active[#FX.active + 1] = instance
	return instance
end

--- Stops an instance's emitters; particles already released live out their lives.
function FX.Stop(instance)
	if instance then instance.stopping = true end
end

local function step(instance)
	local frame = FrameNumber()
	if instance.frame == frame then return instance.alive end
	instance.frame = frame
	local now = CurTime()
	local dt = math.Clamp(now - instance.last, 0, 0.1)
	instance.last = now
	instance.alive = simulate(instance, dt)
	return instance.alive
end

-- View models: start the effects a sequence passes since the last frame.
local watched = setmetatable({}, { __mode = "k" })
local function watch(vm)
	local model = vm:GetModel() or ""
	local last = watched[vm]
	-- Effects an animation starts run to their end, as Unreal's do; a new model (another weapon)
	-- takes its effects with it.
	if last and last.model ~= model then
		for i = #FX.active, 1, -1 do
			if FX.active[i].entity == vm then table.remove(FX.active, i) end
		end
		last = nil
	end
	local sequence = vm:GetSequence()
	local time = vm:GetCycle() * vm:SequenceDuration(sequence)
	watched[vm] = { sequence = sequence, time = time, model = model }
	local events = FX.models[string.lower(model)]
	if not events then return end
	local from = (last and last.sequence == sequence and last.time <= time) and last.time or -1
	for _, event in ipairs(events[vm:GetSequenceName(sequence)] or {}) do
		if event[1] > from and event[1] <= time then FX.Play(event[2], vm, event[3], true) end
	end
end

local function drawPass(viewModel, entity)
	for i = #FX.active, 1, -1 do
		local instance = FX.active[i]
		if instance.viewModel == viewModel and (not viewModel or instance.entity == entity) then
			local valid = instance.entity == nil or IsValid(instance.entity)
			if valid and step(instance) then
				draw(instance)
			else
				table.remove(FX.active, i)
			end
		end
	end
end

-- A view model with lit materials is drawn here rather than by the engine: screenspace_general only
-- tests depth inside render.OverrideDepthEnable, which doesn't last into the engine's own draw. The
-- gamemode (and so the weapon) still gets to hide it first. The engine then skips its own draw and
-- the PostDrawViewModel after it, so effects start and draw from the PostDrawViewModel our draw runs.
local drawingViewModel, shadingViewModel = false, false

local function finishViewModelShading()
	if not shadingViewModel then return end
	render.OverrideDepthEnable(false, false)
	endShading()
	shadingViewModel = false
end

hook.Add("PreDrawViewModel", "GMConverterFX", function(vm, ply, weapon)
	if drawingViewModel or not IsValid(vm) then return end
	local target = render.GetRenderTarget()
	if target and target:GetName() == "_rt_resolvedfullframedepth" then return end
	if not FX.shaded[string.lower(vm:GetModel() or "")] then return end
	if GAMEMODE and GAMEMODE.PreDrawViewModel and GAMEMODE:PreDrawViewModel(vm, ply, weapon) then return true end
	if not beginShading(vm, EyePos()) then return end
	shadingViewModel = true
	drawingViewModel = true
	render.OverrideDepthEnable(true, true)
	vm:DrawModel()
	drawingViewModel = false
	finishViewModelShading()
	return true
end)

hook.Add("PostDrawViewModel", "GMConverterFX", function(vm)
	-- Effects and the hands draw as usual, not with the view model's lit materials.
	finishViewModelShading()
	if not IsValid(vm) then return end
	-- Shader libraries such as GShader draw the view model again into their depth target; effects don't belong there.
	local target = render.GetRenderTarget()
	if target and target:GetName() == "_rt_resolvedfullframedepth" then return end
	watch(vm)
	drawPass(true, vm)
end)

hook.Add("PostDrawTranslucentRenderables", "GMConverterFX", function(depth, skybox, skybox3d)
	if depth or skybox or skybox3d then return end
	drawPass(false)
end)
